cd /private/tmp/ws/22399c9f0631/project && cat > /tmp/probe.mjs <<'EOF'
import { Client } from 'xrpl'
const c = new Client('wss://s.altnet.rippletest.net:51233'); await c.connect()
const f = await c.request({ command: 'feature' })
for (const [k, v] of Object.entries(f.result.features)) if (/MPT|Token|Clawback|Dynamic|Confidential|Domain|Sponsor|fix/i.test(v.name) && /MPT|Dynamic|Confidential|Clawback|Sponsor/i.test(v.name)) console.log(v.name, v.enabled, v.supported)
const ai = await c.request({ command: 'account_info', account: 'rpg7oiiU895LjYpwAkw3wND2CnU9nUYwsx', ledger_index: 'validated' })
console.log(JSON.stringify(ai.result.account_data), ai.result.account_flags)
const ao = await c.request({ command: 'account_objects', account: 'rpg7oiiU895LjYpwAkw3wND2CnU9nUYwsx', ledger_index: 'validated' })
console.log(JSON.stringify(ao.result.account_objects))
const s = await c.request({ command: 'server_info' }); console.log(s.result.info.build_version, JSON.stringify(s.result.info.validated_ledger))
await c.disconnect()
EOF
cp /tmp/probe.mjs ./probe.mjs && node probe.mjs; rm probe.mjs

