cat > scratch/exp.mjs <<'EOF'
import { Client } from 'xrpl'
const c = new Client('wss://s.altnet.rippletest.net:51233'); await c.connect()
const [{wallet: I}, {wallet: H1}, {wallet: H2}] = await Promise.all([c.fundWallet(), c.fundWallet(), c.fundWallet()])
async function tx(w, t, label) {
  try {
    const r = await c.submitAndWait({ ...t, Account: w.address }, { wallet: w, autofill: true })
    console.log(label.padEnd(45), r.result.meta.TransactionResult, r.result.validated); return r
  } catch (e) { console.log(label.padEnd(45), 'THROW', e.message, JSON.stringify(e.data?.engine_result ?? '')) }
}
const bal = async (h) => { try { const r = await c.request({ command:'ledger_entry', mptoken: { mpt_issuance_id: id, account: h.address }, ledger_index:'validated' }); return `${r.result.node.MPTAmount ?? 0} flags=${r.result.node.Flags}` } catch(e) { return 'none' } }
const cr = await tx(I, { TransactionType:'MPTokenIssuanceCreate', Flags: 2|4|32|64, AssetScale:0 }, 'create')
const id = cr.result.meta.mpt_issuance_id; console.log('id', id)
const pay = (from, to, v, l) => tx(from, { TransactionType:'Payment', Destination: to.address, Amount: { mpt_issuance_id: id, value: String(v) } }, l)
await pay(I, H1, 10, 'pay to non-opted-in H1')
await tx(H1, { TransactionType:'MPTokenAuthorize', MPTokenIssuanceID: id }, 'H1 opt-in')
await pay(I, H1, 10, 'pay to opted-in unauthorized H1')
await tx(I, { TransactionType:'MPTokenAuthorize', MPTokenIssuanceID: id, Holder: H1.address }, 'issuer auth H1')
await tx(H2, { TransactionType:'MPTokenAuthorize', MPTokenIssuanceID: id }, 'H2 opt-in')
await tx(I, { TransactionType:'MPTokenAuthorize', MPTokenIssuanceID: id, Holder: H2.address }, 'issuer auth H2')
await pay(I, H1, 100, 'pay 100 to H1'); await pay(I, H2, 100, 'pay 100 to H2')
// individual lock
await tx(I, { TransactionType:'MPTokenIssuanceSet', MPTokenIssuanceID: id, Holder: H1.address, Flags: 1 }, 'lock H1')
await pay(H1, H2, 1, 'locked H1 -> H2'); await pay(H2, H1, 1, 'H2 -> locked H1')
await pay(I, H1, 1, 'issuer -> locked H1'); await pay(H1, {address: I.address}, 1, 'locked H1 -> issuer (redeem)')
await tx(I, { TransactionType:'Clawback', Holder: H1.address, Amount: { mpt_issuance_id: id, value: '5' } }, 'clawback 5 from locked H1')
await tx(I, { TransactionType:'MPTokenIssuanceSet', MPTokenIssuanceID: id, Holder: H1.address, Flags: 1 }, 'lock H1 again (idempotent?)')
await tx(I, { TransactionType:'MPTokenIssuanceSet', MPTokenIssuanceID: id, Holder: H1.address, Flags: 2 }, 'unlock H1')
await pay(H1, H2, 1, 'unlocked H1 -> H2')
// global lock
await tx(I, { TransactionType:'MPTokenIssuanceSet', MPTokenIssuanceID: id, Flags: 1 }, 'global lock')
