    private readonly client: Client,
    readonly wallet: Wallet,
    options: SubmitterOptions = {},
  ) {
    this.ledgerOffset = options.ledgerOffset ?? 20;
    this.maxFeeDrops = options.maxFeeDrops ?? 5000;
