import assert from 'node:assert/strict';
import { test } from 'node:test';
import { InvalidInputError, MAX_MPT_AMOUNT, fromBaseUnits, parseAmount, parsePositiveAmount, toBaseUnits } from '../src/index.js';

test('parseAmount accepts bigint and canonical integer strings', () => {
  assert.equal(parseAmount(500n), 500n);
  assert.equal(parseAmount('0'), 0n);
  assert.equal(parseAmount(MAX_MPT_AMOUNT.toString()), MAX_MPT_AMOUNT);
});

test('parseAmount rejects floats, negatives, leading zeros, overflow and numbers', () => {
  for (const bad of ['1.5', '-1', '01', '', ' 1', '1e3', (MAX_MPT_AMOUNT + 1n).toString()]) {
    assert.throws(() => parseAmount(bad), InvalidInputError, bad);
  }
  assert.throws(() => parseAmount(-1n), InvalidInputError);
  assert.throws(() => parseAmount(5 as unknown as string), InvalidInputError);
  assert.throws(() => parsePositiveAmount(0n), InvalidInputError);
});

test('toBaseUnits / fromBaseUnits round-trip without rounding', () => {
  assert.equal(toBaseUnits('12.5', 2), 1250n);
  assert.equal(toBaseUnits('12', 2), 1200n);
  assert.equal(toBaseUnits('0.01', 2), 1n);
  assert.equal(toBaseUnits('500', 0), 500n);
  assert.throws(() => toBaseUnits('0.001', 2), InvalidInputError);
  assert.throws(() => toBaseUnits('1,5', 2), InvalidInputError);
  assert.equal(fromBaseUnits(1250n, 2), '12.50');
  assert.equal(fromBaseUnits(1n, 2), '0.01');
  assert.equal(fromBaseUnits(500n, 0), '500');
});
EOF
cat > test/banRegistry.test.ts <<'EOF'
import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { test } from 'node:test';
import { FileBanRegistry, InMemoryBanRegistry } from '../src/index.js';

const ID = '0'.repeat(48);
const rec = (address: string, issuanceId = ID) => ({ address, issuanceId, reason: 'r', bannedAt: '2026-01-01T00:00:00.000Z' });

for (const [name, make] of [
  ['InMemoryBanRegistry', async () => ({ reg: new InMemoryBanRegistry(), cleanup: async () => {} })],
  [
    'FileBanRegistry',
    async () => {
      const dir = await mkdtemp(join(tmpdir(), 'bans-'));
      return { reg: new FileBanRegistry(join(dir, 'sub', 'bans.json')), cleanup: () => rm(dir, { recursive: true }) };
    },
  ],
] as const) {
  test(`${name}: add/get/list, idempotent, scoped per issuance, concurrent-safe`, async () => {
    const { reg, cleanup } = await make();
    try {
      assert.equal(await reg.get(ID, 'rA'), undefined);
      await Promise.all([reg.add(rec('rA')), reg.add(rec('rB')), reg.add(rec('rA')), reg.add(rec('rA', 'F'.repeat(48)))]);
      assert.equal((await reg.get(ID, 'rA'))?.address, 'rA');
      assert.deepEqual((await reg.list(ID)).map((r) => r.address).sort(), ['rA', 'rB']);
      assert.equal((await reg.list('F'.repeat(48))).length, 1);
    } finally {
      await cleanup();
    }
  });
}

test('FileBanRegistry persists across instances', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'bans-'));
  try {
    const path = join(dir, 'bans.json');
    await new FileBanRegistry(path).add(rec('rA'));
    assert.equal((await new FileBanRegistry(path).get(ID, 'rA'))?.reason, 'r');
    assert.ok(Array.isArray(JSON.parse(await readFile(path, 'utf8'))));
  } finally {
    await rm(dir, { recursive: true });
  }
});
EOF
