  await s.issuer.issue(H, 500n);
  assert.equal(s.ledger.holders.get(H)?.balance, 500n);
  assert.equal(s.events.at(-1)?.outcome, 'success');
  assert.equal(s.events.at(-1)?.amount, '500');
});

